// Ordinary Rails forms handle persistence, redirects and validation errors.
// JavaScript only supplies the interactions those forms need.
document.addEventListener("submit", event => {
  const message = event.target.dataset.confirm;
  if (message && !window.confirm(message)) event.preventDefault();
});

document.addEventListener("change", event => {
  if (event.target.matches("[data-submit-on-change]")) event.target.form.requestSubmit();
});

function setupQuestionEditor(form) {
  const rows = form.querySelector(".option-rows");
  const blankRow = form.querySelector("[data-blank-row]");
  const add = form.querySelector("[data-add-option]");

  function numberRows() {
    Array.from(rows.children).forEach((row, index) => {
      const label = `Option ${index + 1}`;
      const field = row.querySelector("input[type=text]");
      field.placeholder = label;
      field.setAttribute("aria-label", label);
      row.querySelector("input[type=checkbox]").setAttribute("aria-label", `${label} is correct`);
      row.querySelector("button").setAttribute("aria-label", `Remove option ${index + 1}`);
    });
  }

  add.addEventListener("click", () => {
    rows.append(blankRow.content.cloneNode(true));
    numberRows();
    rows.lastElementChild.querySelector("input").focus();
  });

  rows.addEventListener("click", event => {
    const remove = event.target.closest("[data-remove-option]");
    if (!remove) return;
    const row = remove.closest(".option-row");
    const sibling = row.nextElementSibling || row.previousElementSibling;
    row.remove();
    numberRows();
    (sibling?.querySelector("input") || add).focus();
  });
}

document.querySelectorAll("[data-question-editor]").forEach(setupQuestionEditor);
